1	//! i8-quantized vector segments with exact brute-force KNN.
2	//!
3	//! Same publish discipline as the text shards (magic/version header,
4	//! tmp + fsync + rename, immutable segments). At corpus scale (≤ a few
5	//! million chunks) an exact scan with metadata pre-filtering beats an ANN
6	//! graph: no recall loss, trivial filtering, no extra dependency.
7	//!
8	//! Layout (little-endian):
9	//! ```text
10	//! header (fixed 96 bytes):
11	//!   magic  b"GPXVECS1"                8
12	//!   version u32                       4
13	//!   dim u32                           4
14	//!   count u64                         8
15	//!   model_id [u8; 64] (zero-padded)  64
16	//!   reserved 8
17	//! rows (count × (16 + dim)):
18	//!   chunk_id u64 | scale f32 | reserved u32 | i8[dim]
19	//! ```
20	
21	use std::fs::{self, File, OpenOptions};
22	use std::io::{BufWriter, Write};
23	use std::path::{Path, PathBuf};
24	
25	use memmap2::Mmap;
26	use serde::{Deserialize, Serialize};
27	
28	pub const MAGIC: &[u8; 8] = b"GPXVECS1";
29	pub const VERSION: u32 = 1;
30	const HEADER_LEN: usize = 96;
31	
32	#[derive(Debug, Default, Serialize, Deserialize)]
33	pub struct VectorMeta {
34	    pub model_id: String,
35	    /// `crate::embed::embedder_revision` of the model when the vectors were
36	    /// written: the same model id can embed differently across library
37	    /// releases, and vectors of two revisions must not be mixed. Absent in
38	    /// stores written before it existed, which reads as revision 0.
39	    #[serde(default)]
40	    pub revision: u32,
41	    pub dim: usize,
42	    pub segments: Vec<String>,
43	    /// Highest chunk_id stored, for append bookkeeping.
44	    pub last_chunk_id: i64,
45	}
46	
47	pub struct VectorStore {
48	    dir: PathBuf,
49	    pub meta: VectorMeta,
50	}
51	
52	pub struct OpenSegment {
53	    mmap: Mmap,
54	    dim: usize,
55	    count: usize,
56	}
57	
58	impl VectorStore {
59	    pub fn open(dir: &Path) -> Result<Self, String> {
60	        fs::create_dir_all(dir).map_err(|e| format!("vectors dir: {e}"))?;
61	        let meta_path = dir.join("meta.json");
62	        let meta = match fs::read(&meta_path) {
63	            Ok(bytes) => {
64	                serde_json::from_slice(&bytes).map_err(|e| format!("corrupt vector meta: {e}"))?
65	            }
66	            Err(_) => VectorMeta::default(),
67	        };
68	        Ok(Self {
69	            dir: dir.to_path_buf(),
70	            meta,
71	        })
72	    }
73	
74	    /// Refuse to serve or extend a store built with a different model.
75	    pub fn check_model(&self, model_id: &str, dim: usize) -> Result<(), String> {
76	        if self.meta.model_id.is_empty() {
77	            return Ok(());
78	        }
79	        if self.meta.model_id != model_id || self.meta.dim != dim {
80	            return Err(format!(
81	                "vector store was built with model '{}' ({}d) but the active model is '{}' ({}d) — run `pixel recall embed --rebuild`",
82	                self.meta.model_id, self.meta.dim, model_id, dim
83	            ));
84	        }
85	        Ok(())
86	    }
87	
88	    /// True when the stored vectors were written by an older (or newer)
89	    /// revision of the model the store is built with: they no longer match
90	    /// what the model embeds today, so the store must be re-embedded.
91	    pub fn stale_revision(&self) -> bool {
92	        !self.meta.model_id.is_empty()
93	            && self.meta.revision != crate::embed::embedder_revision(&self.meta.model_id)
94	    }
95	
96	    /// Drop every segment but keep the model, now at its current revision:
97	    /// the store stays bound to the model it was built with while the
98	    /// corpus is embedded again.
99	    pub fn reset_for_reembed(&mut self) -> Result<(), String> {
100	        for seg in &self.meta.segments {
101	            let _ = fs::remove_file(self.dir.join(seg));
102	        }
103	        self.meta.segments.clear();
104	        self.meta.last_chunk_id = 0;
105	        self.meta.revision = crate::embed::embedder_revision(&self.meta.model_id);
106	        self.write_meta()
107	    }
108	
109	    fn write_meta(&self) -> Result<(), String> {
110	        let tmp = self.dir.join("meta.json.tmp");
111	        fs::write(&tmp, serde_json::to_vec_pretty(&self.meta).unwrap())
112	            .map_err(|e| e.to_string())?;
113	        fs::rename(&tmp, self.dir.join("meta.json")).map_err(|e| e.to_string())
114	    }
115	
116	    /// Write one immutable segment of (chunk_id, f32 vector) rows.
117	    pub fn append_segment(
118	        &mut self,
119	        model_id: &str,
120	        dim: usize,
121	        rows: &[(i64, Vec<f32>)],
122	    ) -> Result<(), String> {
123	        if rows.is_empty() {
124	            return Ok(());
125	        }
126	        self.check_model(model_id, dim)?;
127	        let seq = self.meta.segments.len() as u64 + 1;
128	        let name = format!("seg-{seq:06}.vec");
129	        let tmp = self.dir.join(format!("{name}.tmp"));
130	        {
131	            let file = OpenOptions::new()
132	                .write(true)
133	                .create(true)
134	                .truncate(true)
135	                .open(&tmp)
136	                .map_err(|e| e.to_string())?;
137	            let mut w = BufWriter::new(file);
138	            let mut header = [0u8; HEADER_LEN];
139	            header[0..8].copy_from_slice(MAGIC);
140	            header[8..12].copy_from_slice(&VERSION.to_le_bytes());
141	            header[12..16].copy_from_slice(&(dim as u32).to_le_bytes());
142	            header[16..24].copy_from_slice(&(rows.len() as u64).to_le_bytes());
143	            let mid = model_id.as_bytes();
144	            header[24..24 + mid.len().min(64)].copy_from_slice(&mid[..mid.len().min(64)]);
145	            w.write_all(&header).map_err(|e| e.to_string())?;
146	            let mut quantized = vec![0i8; dim];
147	            for (chunk_id, vec) in rows {
148	                if vec.len() != dim {
149	                    return Err("vector dim mismatch".to_string());
150	                }
151	                let max_abs = vec.iter().fold(0f32, |m, v| m.max(v.abs()));
152	                let scale = if max_abs > 0.0 { max_abs / 127.0 } else { 1.0 };
153	                for (q, v) in quantized.iter_mut().zip(vec) {
154	                    *q = (v / scale).round().clamp(-127.0, 127.0) as i8;
155	                }
156	                w.write_all(&chunk_id.to_le_bytes())
157	                    .map_err(|e| e.to_string())?;
158	                w.write_all(&scale.to_le_bytes())
159	                    .map_err(|e| e.to_string())?;
160	                w.write_all(&0u32.to_le_bytes())
161	                    .map_err(|e| e.to_string())?;
162	                // SAFETY: `quantized` is a Vec<i8> of exactly `dim` elements; i8 and u8
163	                // share size and alignment, and the slice does not outlive `quantized`.
164	                let bytes: &[u8] =
165	                    unsafe { std::slice::from_raw_parts(quantized.as_ptr().cast::<u8>(), dim) };
166	                w.write_all(bytes).map_err(|e| e.to_string())?;
167	                self.meta.last_chunk_id = self.meta.last_chunk_id.max(*chunk_id);
168	            }
169	            w.flush().map_err(|e| e.to_string())?;
170	            w.get_ref().sync_all().map_err(|e| e.to_string())?;
171	        }
172	        fs::rename(&tmp, self.dir.join(&name)).map_err(|e| e.to_string())?;
173	        if self.meta.segments.is_empty() {
174	            self.meta.revision = crate::embed::embedder_revision(model_id);
175	        }
176	        self.meta.model_id = model_id.to_string();
177	        self.meta.dim = dim;
178	        self.meta.segments.push(name);
179	        self.write_meta()
180	    }
181	
182	    /// Drop every segment (model change / rebuild).
183	    pub fn clear(&mut self) -> Result<(), String> {
184	        for seg in &self.meta.segments {
185	            let _ = fs::remove_file(self.dir.join(seg));
186	        }
187	        self.meta = VectorMeta::default();
188	        self.write_meta()
189	    }
190	
191	    pub fn open_segments(&self) -> Vec<OpenSegment> {
192	        self.meta
193	            .segments
194	            .iter()
195	            .filter_map(|name| OpenSegment::open(&self.dir.join(name)).ok())
196	            .collect()
197	    }
198	
199	    /// Exact KNN over every segment. `allowed` (when present) is the set of
200	    /// chunk ids that pass the metadata filters — exact pre-filtering.
201	    pub fn knn(
202	        &self,
203	        query: &[f32],
204	        k: usize,
205	        allowed: Option<&std::collections::HashSet<i64>>,
206	    ) -> Vec<(i64, f32)> {
207	        let mut best: Vec<(i64, f32)> = Vec::with_capacity(k + 1);
208	        for seg in self.open_segments() {
209	            seg.scan(query, |chunk_id, score| {
210	                if let Some(set) = allowed
211	                    && !set.contains(&chunk_id)
212	                {
213	                    return;
214	                }
215	                if best.len() < k {
216	                    best.push((chunk_id, score));
217	                    if best.len() == k {
218	                        best.sort_by(|a, b| b.1.total_cmp(&a.1));
219	                    }
220	                } else if score > best[k - 1].1 {
221	                    best[k - 1] = (chunk_id, score);
222	                    let mut i = k - 1;
223	                    while i > 0 && best[i].1 > best[i - 1].1 {
224	                        best.swap(i, i - 1);
225	                        i -= 1;
226	                    }
227	                }
228	            });
229	        }
230	        best.sort_by(|a, b| b.1.total_cmp(&a.1));
231	        best
232	    }
233	}
234	
235	impl OpenSegment {
236	    pub fn open(path: &Path) -> Result<Self, String> {
237	        let file = File::open(path).map_err(|e| e.to_string())?;
238	        // SAFETY: segments are written to a temp path and renamed into place
239	        // (`append` above) and never modified afterwards, so the mapping cannot
240	        // change under us; the header and every offset are validated below.
241	        let mmap = unsafe { Mmap::map(&file).map_err(|e| e.to_string())? };
242	        if mmap.len() < HEADER_LEN || &mmap[0..8] != MAGIC {
243	            return Err("bad vector segment header".to_string());
244	        }
245	        let version = u32::from_le_bytes(mmap[8..12].try_into().unwrap());
246	        if version != VERSION {
247	            return Err(format!("vector segment version {version}"));
248	        }
249	        let dim = u32::from_le_bytes(mmap[12..16].try_into().unwrap()) as usize;
250	        let count = u64::from_le_bytes(mmap[16..24].try_into().unwrap()) as usize;
251	        let row = 16 + dim;
252	        if HEADER_LEN + count * row > mmap.len() {
253	            return Err("truncated vector segment".to_string());
254	        }
255	        Ok(Self { mmap, dim, count })
256	    }
257	
258	    /// Visit every row with its cosine-proportional score (dot product of
259	    /// the normalized query against the quantized vector).
260	    fn scan(&self, query: &[f32], mut visit: impl FnMut(i64, f32)) {
261	        if query.len() != self.dim {
262	            return;
263	        }
264	        let row_len = 16 + self.dim;
265	        for i in 0..self.count {
266	            let off = HEADER_LEN + i * row_len;
267	            let chunk_id = i64::from_le_bytes(self.mmap[off..off + 8].try_into().unwrap());
268	            let scale = f32::from_le_bytes(self.mmap[off + 8..off + 12].try_into().unwrap());
269	            let vec_bytes = &self.mmap[off + 16..off + 16 + self.dim];
270	            let mut dot = 0f32;
271	            for (q, b) in query.iter().zip(vec_bytes) {
272	                dot += q * (*b as i8 as f32);
273	            }
274	            visit(chunk_id, dot * scale);
275	        }
276	    }
277	}
278	
279	#[cfg(test)]
280	mod tests {
281	    use super::*;
282	
283	    #[test]
284	    fn roundtrip_and_knn() {
285	        let dir = std::env::temp_dir().join(format!("gpx-vec-test-{}", std::process::id()));
286	        let _ = std::fs::remove_dir_all(&dir);
287	        let mut store = VectorStore::open(&dir).unwrap();
288	        let rows = vec![
289	            (1i64, vec![1.0, 0.0, 0.0]),
290	            (2, vec![0.0, 1.0, 0.0]),
291	            (3, vec![0.7, 0.7, 0.0]),
292	        ];
293	        store.append_segment("test-model", 3, &rows).unwrap();
294	        let hits = store.knn(&[1.0, 0.0, 0.0], 2, None);
295	        assert_eq!(hits[0].0, 1);
296	        assert_eq!(hits[1].0, 3);
297	        // Filtering excludes the best hit.
298	        let allowed: std::collections::HashSet<i64> = [2, 3].into_iter().collect();
299	        let hits = store.knn(&[1.0, 0.0, 0.0], 2, Some(&allowed));
300	        assert_eq!(hits[0].0, 3);
301	        // Model mismatch is a loud error.
302	        assert!(store.check_model("other-model", 3).is_err());
303	        let _ = std::fs::remove_dir_all(&dir);
304	    }
305	
306	    /// A store is stale only when bound to a model whose revision moved
307	    /// since it was written; a reset keeps the model and takes the current
308	    /// revision.
309	    #[test]
310	    fn stale_revision_and_reset_for_reembed_track_the_model_revision() {
311	        let dir = tempfile::tempdir().unwrap();
312	        let mut store = VectorStore::open(dir.path()).unwrap();
313	        assert!(!store.stale_revision(), "an empty store is never stale");
314	        let potion = crate::embed::POTION_REPO;
315	        store
316	            .append_segment(potion, 3, &[(7i64, vec![1.0, 0.0, 0.0])])
317	            .unwrap();
318	        assert_eq!(store.meta.revision, crate::embed::MODEL2VEC_REVISION);
319	        assert!(!store.stale_revision());
320	        let segment = dir.path().join(&store.meta.segments[0]);
321	        assert!(segment.exists());
322	
323	        store.meta.revision = 0;
324	        assert!(store.stale_revision());
325	        store.reset_for_reembed().unwrap();
326	        assert!(store.meta.segments.is_empty());
327	        assert!(!segment.exists(), "old segment files removed");
328	        assert_eq!(store.meta.last_chunk_id, 0);
329	        assert_eq!(store.meta.model_id, potion);
330	        assert_eq!(store.meta.revision, crate::embed::MODEL2VEC_REVISION);
331	        let reread = VectorStore::open(dir.path()).unwrap();
332	        assert!(!reread.stale_revision(), "the reset is on disk");
333	
334	        let mut other = VectorStore::open(&dir.path().join("other")).unwrap();
335	        other
336	            .append_segment(crate::embed::E5_MODEL_ID, 3, &[(1i64, vec![0.0, 1.0, 0.0])])
337	            .unwrap();
338	        assert_eq!(other.meta.revision, 0);
339	        assert!(
340	            !other.stale_revision(),
341	            "a model at revision 0 written at 0"
342	        );
343	    }
344	}
