1	//! Semantic code search over a code tree via static embeddings.
2	//!
3	//! `ask(root, query, k, max_files)` answers open-ended questions like "how is
4	//! authentication handled?" by embedding the question and every candidate code
5	//! chunk (a file cut along its symbols, [`crate::code_chunks`]), then fusing semantic ranks with a BM25 lexical rank (best chunk per
6	//! file); tests, configuration, data and docs rank below code unless the
7	//! question names them ([`FileKind`]).
8	//! Reuses this crate's embedding seam
9	//! (`Embedder` trait + `PotionEmbedder` behind the `model2vec` feature), so the
10	//! model downloads once into the shared recall model cache on first use and the
11	//! ML dependency stays behind a feature.
12	//!
13	//! Chunk vectors persist between questions in `.pixel/code-vectors/` when the
14	//! search root carries a pixel index ([`vector_cache_for`],
15	//! [`crate::code_vectors`]): a warm question embeds only the chunks whose text
16	//! changed, and ranks exactly as an uncached one.
17	//!
18	//! This is an AUGMENTATIVE channel, deliberately NOT a replacement for
19	//! `resolve`/`search`: deterministic resolution keeps its contract; `ask`
20	//! adds a semantic layer on top. NDCG is the gate (see
21	//! crates/pixel-bench/benches/ndcg_relevance.rs).
22	
23	use std::collections::{BTreeMap, HashMap, HashSet};
24	use std::path::{Path, PathBuf};
25	
26	use crate::code_vectors::{ChunkKey, Namespace, Store};
27	use rayon::prelude::*;
28	
29	use crate::code_chunks::code_chunks;
30	use crate::embed::EmbedKind;
31	
32	/// One ranked hit: a file matched for the question, with a representative
33	/// snippet (head of the best-matching chunk), cosine score and RRF ordering key.
34	pub struct AskHit {
35	    pub path: String,
36	    /// Compatibility alias of semantic_score (cosine), not the ordering key.
37	    pub score: f32,
38	    pub semantic_score: f32,
39	    pub ranking_score: f64,
40	    pub lexical_matches: usize,
41	    /// BM25 score of the file's best chunk for the question's terms.
42	    pub lexical_score: f64,
43	    /// The kind of file this is when its score was lowered for it
44	    /// ([`FileKind`], [`DEMOTED_WEIGHT`]); `None` for code and for a kind the
45	    /// question names.
46	    pub demoted: Option<FileKind>,
47	    pub query_terms: usize,
48	    pub snippet: String,
49	}
50	
51	const MAX_FILE_BYTES: usize = 512 * 1024;
52	
53	/// Most files a question without a `--max-files` budget embeds: a guard
54	/// against a runaway universe, not a budget. A question searches every
55	/// eligible file by default (persisted vectors make a warm question pay only
56	/// for the chunks that changed); above this ceiling it searches a
57	/// deterministic sample of it ([`sample_across_tree`]) and says so
58	/// ([`FileBudget::Ceiling`]). An explicit `--max-files` replaces it, above
59	/// or below.
60	///
61	/// Sized from measurements (2026-09-27): yespark-rails, the largest
62	/// repository at hand, has 11 299 eligible files, and 50 000 is the graph
63	/// builder's own walk ceiling (`PIXEL_GRAPH_MAX_FILES`). A home directory
64	/// has 347 611: uncapped, that is about 1.5 million chunks, some 1.5 GB of
65	/// vectors held in memory and minutes of embedding, never persisted there.
66	pub const UNBUDGETED_FILE_CEILING: usize = 50_000;
67	
68	/// Default for `pixel search-meaning --limit`: ranked hits returned. Ten, so a
69	/// recall@10 measurement reads the list a user actually gets.
70	pub const DEFAULT_LIMIT: usize = 10;
71	
72	/// Version of how `search-meaning` cuts a file into the texts it embeds. Part
73	/// of every persisted vector's key ([`crate::code_vectors::Namespace`]): bump
74	/// it, with a line below, when the chunking or the text sent to the model for
75	/// a chunk changes, and no vector of the old chunking is served again.
76	///
77	/// History: 1 = [`crate::embed::chunk_offsets`] windows (`embed::CHUNK_MAX`
78	/// bytes, `embed::CHUNK_OVERLAP` of overlap), each embedded verbatim.
79	/// 2 = symbol chunks ([`code_chunks`]): a file cut along its tree-sitter
80	/// symbols with their doc comments, pieces packed up to
81	/// [`crate::code_chunks::PACK_MAX`] bytes, windows only for unparsed files
82	/// and oversize pieces.
83	pub const CHUNKER_VERSION: u32 = 2;
84	
85	/// Whether a question's chunk vectors persist in `.pixel/code-vectors/`, and
86	/// when they do not, why.
87	#[derive(Debug, Default, Clone, Copy, PartialEq, Eq, serde::Serialize)]
88	#[serde(rename_all = "snake_case")]
89	pub enum VectorCache {
90	    /// Not asked for: the daemon's semantic fallback embeds in memory only.
91	    #[default]
92	    Disabled,
93	    /// The search root carries no pixel index (a subtree, an unindexed
94	    /// tree): nothing is written there.
95	    NoIndex,
96	    /// The search root is the home directory, whose `.pixel` holds global
97	    /// state: nothing is written there.
98	    HomeDirectory,
99	    /// Read from and written to `<root>/.pixel/code-vectors/`.
100	    Persisted,
101	}
102	
103	/// Where `root`'s question keeps its chunk vectors: persisted only when
104	/// `root` itself carries a pixel index (`.pixel/base.shard`), so a subtree
105	/// or an unindexed tree gets no `.pixel` written into it, and never when
106	/// `root` is `home`, whatever it carries.
107	pub fn vector_cache_for(root: &Path, home: Option<&Path>) -> VectorCache {
108	    let canonical = |path: &Path| path.canonicalize().unwrap_or_else(|_| path.to_path_buf());
109	    if home.is_some_and(|home| canonical(home) == canonical(root)) {
110	        return VectorCache::HomeDirectory;
111	    }
112	    let index = root
113	        .join(pixel_index::index::SHARD_DIR)
114	        .join(pixel_index::index::SHARD_FILE);
115	    if index.is_file() {
116	        VectorCache::Persisted
117	    } else {
118	        VectorCache::NoIndex
119	    }
120	}
121	
122	/// Which file limit a question ran under.
123	#[derive(Debug, Default, Clone, Copy, PartialEq, Eq, serde::Serialize)]
124	#[serde(rename_all = "snake_case")]
125	pub enum FileBudget {
126	    /// No `--max-files` and the universe within [`UNBUDGETED_FILE_CEILING`]:
127	    /// every eligible file was in reach.
128	    #[default]
129	    None,
130	    /// The caller's `--max-files` (or the semantic fallback's own budget).
131	    Explicit,
132	    /// No `--max-files`, and more eligible files than
133	    /// [`UNBUDGETED_FILE_CEILING`]: a sample of that size was searched.
134	    Ceiling,
135	}
136	
137	/// What one question covered: the eligible universe, the part embedded, and
138	/// every reason a file was left out.
139	#[derive(Default, serde::Serialize)]
140	pub struct AskCoverage {
141	    /// Eligible files under the root (walk policy, excluded directories,
142	    /// nested checkouts and extensions applied), whether searched or not.
143	    pub candidate_files: usize,
144	    /// Files actually read, chunked and embedded.
145	    pub searched_files: usize,
146	    /// The file limit in force: the explicit budget, or
147	    /// [`UNBUDGETED_FILE_CEILING`] when an unbudgeted question outgrew it.
148	    /// `None` (JSON `null`) when there was none: no `--max-files` and every
149	    /// eligible file in reach. `file_budget` says which of the three.
150	    pub max_files: Option<usize>,
151	    pub file_budget: FileBudget,
152	    /// More than `max_files` files were eligible: only a sample was searched.
153	    pub file_limit_reached: bool,
154	    pub skipped_files: usize,
155	    pub empty_files: usize,
156	    pub traversal_errors: usize,
157	    pub result_limit_reached: bool,
158	    pub scope: &'static str,
159	    pub degraded: bool,
160	    /// Chunks ranked: every searched file's symbol chunks
161	    /// ([`crate::code_chunks`]).
162	    pub chunks: usize,
163	    /// Chunks the model embedded for this question, each distinct text once.
164	    pub embedded_chunks: usize,
165	    /// Chunks whose vector came from `.pixel/code-vectors/`.
166	    pub cached_chunks: usize,
167	    pub vector_cache: VectorCache,
168	    /// Failures of the vector store (unreadable, missing or altered segment,
169	    /// failed write). The chunks involved were embedded again, so the answer
170	    /// is complete; only the saving was lost. Sets `degraded`.
171	    pub vector_cache_errors: Vec<String>,
172	}
173	
174	impl AskCoverage {
175	    /// The line a human reader gets when the question searched a sample, so
176	    /// a missing answer is never passed off as an absent one. `None` when the
177	    /// whole eligible universe was in reach.
178	    pub fn sample_note(&self) -> Option<String> {
179	        if !self.file_limit_reached {
180	            return None;
181	        }
182	        let limit = self.max_files.unwrap_or_default();
183	        let (why, remedy) = match self.file_budget {
184	            FileBudget::Ceiling => (
185	                format!("safety ceiling of {limit} files without --max-files"),
186	                "pass a larger --max-files",
187	            ),
188	            FileBudget::Explicit | FileBudget::None => {
189	                (format!("--max-files {limit}"), "raise --max-files")
190	            }
191	        };
192	        Some(format!(
193	            "searched a deterministic sample of {} of {} eligible files ({why}); {remedy} to search them all",
194	            self.searched_files, self.candidate_files
195	        ))
196	    }
197	
198	    /// The line a human reader gets when the vector store failed, so a slow
199	    /// or degraded answer carries its reason. `None` when it did not.
200	    pub fn vector_cache_note(&self) -> Option<String> {
201	        (!self.vector_cache_errors.is_empty()).then(|| {
202	            format!(
203	                "vector cache: {}; the affected chunks were embedded again",
204	                self.vector_cache_errors.join("; ")
205	            )
206	        })
207	    }
208	}
209	
210	pub struct AskResult {
211	    pub hits: Vec<AskHit>,
212	    pub coverage: AskCoverage,
213	}
214	
215	/// The files one question embeds, absolute, sorted by repository-relative
216	/// path, with the coverage of the walk.
217	///
218	/// The universe is the indexing walk policy ([`pixel_index::index::policy_walk`],
219	/// the walk behind `policy_file_paths`): `.gitignore`/`.ignore` honoured even
220	/// without git, `.git`, `.pixel` and the default-ignored build and dependency
221	/// directories pruned, symlinks never followed, nothing written. On top of it,
222	/// a path is eligible when no directory on it is a [`skip_dir`] name or the top
223	/// of a nested checkout, and its name is a [`is_code_file`] one. The walk is
224	/// iterated directly rather than through `policy_file_paths` so its errors are
225	/// counted in `traversal_errors` instead of vanishing, and non-UTF-8 names
226	/// keep their bytes.
227	///
228	/// `max_files` is the caller's budget; `None` searches every eligible file up
229	/// to [`UNBUDGETED_FILE_CEILING`]. Over the limit in force, the files kept
230	/// are a sample spread over the whole tree ([`sample_across_tree`]);
231	/// `candidate_files` still counts every eligible file, and
232	/// `file_limit_reached` and `degraded` say that the search was partial.
233	fn collect_files(root: &Path, max_files: Option<usize>) -> (Vec<PathBuf>, AskCoverage) {
234	    collect_files_within(root, max_files, UNBUDGETED_FILE_CEILING)
235	}
236	
237	/// [`collect_files`] with the ceiling of an unbudgeted question as a
238	/// parameter, so a test can reach it without 50 000 files.
239	fn collect_files_within(
240	    root: &Path,
241	    max_files: Option<usize>,
242	    ceiling: usize,
243	) -> (Vec<PathBuf>, AskCoverage) {
244	    let mut coverage = AskCoverage {
245	        max_files,
246	        file_budget: if max_files.is_some() {
247	            FileBudget::Explicit
248	        } else {
249	            FileBudget::None
250	        },
251	        scope: "eligible source/document extensions; gitignored files and excluded noise directories skipped; nested checkouts skipped; no symlinks; files <=512KiB; UTF-8 text only",
252	        ..Default::default()
253	    };
254	    if std::fs::symlink_metadata(root).is_ok_and(|m| m.file_type().is_symlink()) {
255	        coverage.skipped_files += 1;
256	        coverage.degraded = true;
257	        return (Vec::new(), coverage);
258	    }
259	    let mut nested = HashMap::new();
260	    let mut eligible = Vec::new();
261	    for entry in pixel_index::index::policy_walk(root) {
262	        let Ok(entry) = entry else {
263	            coverage.traversal_errors += 1;
264	            continue;
265	        };
266	        if !entry.file_type().is_some_and(|kind| kind.is_file()) {
267	            continue;
268	        }
269	        let Ok(relative) = entry.path().strip_prefix(root) else {
270	            continue;
271	        };
272	        if is_eligible(root, relative, &mut nested) {
273	            eligible.push(relative.to_path_buf());
274	        }
275	    }
276	    coverage.candidate_files = eligible.len();
277	    let limit = max_files.unwrap_or(ceiling);
278	    coverage.file_limit_reached = eligible.len() > limit;
279	    if coverage.file_limit_reached && max_files.is_none() {
280	        coverage.file_budget = FileBudget::Ceiling;
281	        coverage.max_files = Some(ceiling);
282	    }
283	    coverage.degraded = coverage.file_limit_reached || coverage.traversal_errors > 0;
284	    let files = sample_across_tree(eligible, limit)
285	        .into_iter()
286	        .map(|relative| root.join(relative))
287	        .collect();
288	    (files, coverage)
289	}
290	
291	/// Whether the walk-admitted file at `relative` (below `root`) is searched:
292	/// no directory on its path is a [`skip_dir`] name or another checkout's top,
293	/// and its name has a code or document extension. `nested` memoises the
294	/// checkout probe per directory, which every file below it would repeat.
295	fn is_eligible(root: &Path, relative: &Path, nested: &mut HashMap<PathBuf, bool>) -> bool {
296	    let Some(name) = relative.file_name() else {
297	        return false;
298	    };
299	    if !is_code_file(&name.to_string_lossy()) {
300	        return false;
301	    }
302	    let mut dir = PathBuf::new();
303	    for component in relative.parent().into_iter().flat_map(Path::components) {
304	        dir.push(component);
305	        if skip_dir(&component.as_os_str().to_string_lossy()) {
306	            return false;
307	        }
308	        let is_checkout = *nested
309	            .entry(dir.clone()) // the memo owns its key; `dir` keeps growing
310	            .or_insert_with(|| is_nested_checkout(&root.join(&dir)));
311	        if is_checkout {
312	            return false;
313	        }
314	    }
315	    true
316	}
317	
318	/// At most `max_files` of the repository-relative `files`, sorted by path.
319	///
320	/// Over the budget, the sample keeps the files with the smallest
321	/// [`sample_key`] (an xxh3 hash of the relative path): every directory is
322	/// represented in proportion to its size, whatever its depth or its place in
323	/// the alphabet, where a walk cut at the budget searched only the shallowest,
324	/// alphabetically-first directories. A hash rather than a stride over the
325	/// sorted list because the sample then depends on each path alone: the same
326	/// tree gives the same sample on every run and from every checkout location,
327	/// and adding or removing one file changes at most one other member, where a
328	/// stride would shift every pick after the edit.
329	///
330	/// Under the budget the ordering pass and `truncate` keep every file, so one
331	/// code path serves both regimes.
332	fn sample_across_tree(mut files: Vec<PathBuf>, max_files: usize) -> Vec<PathBuf> {
333	    files.sort_by_cached_key(|path| (sample_key(path), path.clone()));
334	    files.truncate(max_files);
335	    files.sort();
336	    files
337	}
338	
339	/// Stable, platform-independent sampling key of a repository-relative path.
340	fn sample_key(relative: &Path) -> u64 {
341	    xxhash_rust::xxh3::xxh3_64(relative.as_os_str().as_encoded_bytes())
342	}
343	
344	/// Whether `dir` is the top of another working tree: a linked worktree or a
345	/// submodule (a `.git` file) or a nested clone (a `.git` directory). Its
346	/// files belong to that checkout, often another branch of the same project
347	/// (`git worktree add`, `.claude/worktrees/<name>`), and would rank copies
348	/// of the searched tree's own code; git does not list them either. Only
349	/// directories below the walk root are asked, so the root keeps its `.git`.
350	fn is_nested_checkout(dir: &Path) -> bool {
351	    std::fs::symlink_metadata(dir.join(".git")).is_ok()
352	}
353	
354	fn skip_dir(name: &str) -> bool {
355	    matches!(
356	        name,
357	        "target"
358	            | "node_modules"
359	            | ".git"
360	            | ".pixel"
361	            | "dist"
362	            | "build"
363	            | "vendor"
364	            | ".cache"
365	            | "assets"
366	            | "reference"
367	            | "examples"
368	            | "tests"
369	    )
370	}
371	
372	fn is_code_file(name: &str) -> bool {
373	    let ext = name
374	        .rsplit('.')
375	        .next()
376	        .map(str::to_lowercase)
377	        .unwrap_or_default();
378	    matches!(
379	        ext.as_str(),
380	        "rs" | "toml"
381	            | "py"
382	            | "ts"
383	            | "tsx"
384	            | "js"
385	            | "jsx"
386	            | "go"
387	            | "c"
388	            | "h"
389	            | "cpp"
390	            | "hpp"
391	            | "java"
392	            | "rb"
393	            | "sh"
394	            | "md"
395	            | "json"
396	            | "yaml"
397	            | "yml"
398	            | "sql"
399	            | "zig"
400	            | "swift"
401	            | "kt"
402	            | "css"
403	    )
404	}
405	
406	/// Cosine similarity between two vectors (defensive normalize on top of the
407	/// embedder's built-in L2 normalization).
408	fn cosine(a: &[f32], b: &[f32]) -> f32 {
409	    if a.len() != b.len() || a.is_empty() {
410	        return 0.0;
411	    }
412	    let mut dot = 0.0f32;
413	    let mut na = 0.0f32;
414	    let mut nb = 0.0f32;
415	    for (x, y) in a.iter().zip(b) {
416	        dot += x * y;
417	        na += x * x;
418	        nb += y * y;
419	    }
420	    let denom = (na * nb).sqrt();
421	    if denom > 0.0 { dot / denom } else { 0.0 }
422	}
