449	/// Semantic leads for a query no lexical tier answered, with what the scan
450	/// covered. The similarity scores do not separate related from unrelated
451	/// files (measured on this repository, 2026-09-14: a nonsense query's best
452	/// file scored 0.33, a relevant French question's 0.33 to 0.39), so callers
453	/// present the hits as unverified leads, never as matches.
454	#[derive(Debug, Clone, Default, PartialEq)]
455	pub struct SemanticFallback {
456	    /// `(repo-relative path, cosine similarity)`, best first, at most `limit`.
457	    pub hits: Vec<(String, f64)>,
458	    pub searched_files: usize,
459	    /// More than [`SEMANTIC_FALLBACK_MAX_FILES`] files were eligible: the
460	    /// scan embedded a deterministic sample of them, spread across the tree.
461	    pub file_limit_reached: bool,
462	    /// The fallback was gated off (`PIXEL_SEMANTIC_FALLBACK` unset): no
463	    /// model load and no corpus embed ran. Named so a caller can report
464	    /// "disabled" rather than "searched, found nothing".
465	    pub disabled: bool,
466	}
