468	impl SemanticFallback {
469	    /// Caps a caller names in its epistemics when it shows these hits.
470	    pub fn caps(&self) -> Vec<String> {
471	        if self.disabled {
472	            return vec![
473	                "semantic fallback disabled: set PIXEL_SEMANTIC_FALLBACK=1 to enable".to_string(),
474	            ];
475	        }
476	        if self.hits.is_empty() {
477	            return Vec::new();
478	        }
479	        let mut caps = vec![
480	            "semantic leads are unverified: embedding similarity does not separate related from unrelated files"
481	                .to_string(),
482	        ];
483	        if self.file_limit_reached {
484	            caps.push(format!(
485	                "semantic fallback embedded only a deterministic sample of {} of the eligible files",
486	                self.searched_files
487	            ));
488	        }
489	        caps
490	    }
491	}
