500	    static ENABLED: std::sync::OnceLock<bool> = std::sync::OnceLock::new();
501	    *ENABLED.get_or_init(|| {
502	        std::env::var("PIXEL_SEMANTIC_FALLBACK").is_ok_and(|v| {
503	            matches!(
504	                v.trim().to_ascii_lowercase().as_str(),
505	                "1" | "true" | "yes" | "on"
506	            )
507	        })
508	    })
509	}
