644	/// Rank `files` for `query`: chunk them, take each chunk's vector from
645	/// `store` or the embedder ([`chunk_vectors`]), fuse semantic and lexical
646	/// ranks.
647	fn ask_collected(
648	    root: &Path,
649	    query: &str,
650	    k: usize,
651	    files: Vec<PathBuf>,
652	    mut coverage: AskCoverage,
653	    embedder: &mut dyn crate::embed::Embedder,
654	    store: Option<&Store>,
655	) -> Result<AskResult, String> {
656	    let model_id = embedder.model_id().to_string();
657	    let namespace = Namespace::new(
658	        &model_id,
659	        crate::embed::embedder_revision(&model_id),
660	        CHUNKER_VERSION,
661	    );
662	    // Build the corpus: chunk every file, key every chunk by its text, and
663	    // count the query's terms in each chunk for the lexical channel.
664	    let terms = sorted_query_terms(query);
665	    let mut corpus: Vec<CorpusEntry> = Vec::new();
666	    let mut file_paths: Vec<String> = Vec::new();
667	    // Every chunk's term counts, with the index of its file in `file_paths`.
668	    let mut lexical_chunks: Vec<(usize, pixel_rank::Bm25Doc)> = Vec::new();
669	    // Reading and parsing dominate a warm question: one file per task, the
670	    // results folded back in the files' order.
671	    let read: Vec<FileRead> = files
672	        .par_iter()
673	        .map(|file| read_file(root, file, &terms))
674	        .collect();
675	    for file in read {
676	        let (path, chunks) = match file {
677	            FileRead::Skipped => {
678	                coverage.skipped_files += 1;
679	                continue;
680	            }
681	            FileRead::Empty => {
682	                coverage.empty_files += 1;
683	                continue;
684	            }
685	            FileRead::Searched { path, chunks } => (path, chunks),
686	        };
687	        coverage.searched_files += 1;
688	        let file_index = file_paths.len();
689	        for (chunk, doc) in chunks {
690	            lexical_chunks.push((file_index, doc));
691	            corpus.push(CorpusEntry {
692	                path: path.clone(),
693	                key: namespace.key(&chunk),
694	                text: chunk,
695	            });
696	        }
697	        file_paths.push(path);
698	    }
699	    let lexical = lexical_evidence(&terms, file_paths, lexical_chunks);
700	    coverage.degraded |= coverage.skipped_files > 0;
701	    if corpus.is_empty() {
702	        return Ok(AskResult {
703	            hits: Vec::new(),
704	            coverage,
705	        });
706	    }
707	
708	    // Embed the query and all chunks.
709	    let qvec = embedder
710	        .embed_batch(&[query], EmbedKind::Query)?
711	        .into_iter()
712	        .next()
713	        .ok_or("empty query embedding")?;
714	    validate_vector(&qvec, embedder.dims())?;
715	    let vectors = chunk_vectors(&corpus, &namespace, embedder, store, &mut coverage)?;
716	
717	    // Per-file best score across its chunks.
718	    let mut best: HashMap<String, f32> = HashMap::new();
719	    let mut snippet_of: HashMap<String, String> = HashMap::new();
720	    for entry in &corpus {
721	        let vec = &vectors[&entry.key];
722	        validate_vector(vec, qvec.len())?;
723	        let s = cosine(&qvec, vec);
724	        if best.get(&entry.path).copied().unwrap_or(f32::MIN) < s {
725	            best.insert(entry.path.clone(), s);
726	            snippet_of.insert(entry.path.clone(), make_snippet(&entry.text));
727	        }
728	    }
729	
730	    coverage.result_limit_reached = best.len() > k;
731	    Ok(AskResult {
732	        hits: rank_files(query, &lexical, best, snippet_of, k),
733	        coverage,
734	    })
735	}
