737	/// The vector of every chunk of `corpus`, by key: the ones `store` holds, and
738	/// the rest embedded in one batch, each distinct text once, then saved.
739	///
740	/// A store failure never fails the question: the chunks it could not serve
741	/// are embedded like new ones, the failure is named in
742	/// `coverage.vector_cache_errors` and marks the answer degraded, and the next
743	/// save rebuilds the store. Counts go to `coverage.chunks`,
744	/// `embedded_chunks` and `cached_chunks`.
745	fn chunk_vectors(
746	    corpus: &[CorpusEntry],
747	    namespace: &Namespace,
748	    embedder: &mut dyn crate::embed::Embedder,
749	    store: Option<&Store>,
750	    coverage: &mut AskCoverage,
751	) -> Result<HashMap<ChunkKey, Vec<f32>>, String> {
752	    let dims = embedder.dims();
753	    let wanted: HashSet<ChunkKey> = corpus.iter().map(|entry| entry.key).collect();
754	    let crate::code_vectors::Loaded {
755	        mut vectors,
756	        stored_rows,
757	        errors,
758	    } = store
759	        .map(|store| store.load(namespace, dims, &wanted))
760	        .unwrap_or_default();
761	    let rebuild = !errors.is_empty();
762	    coverage.vector_cache_errors.extend(errors);
763	    let mut fresh = Vec::new();
764	    let mut texts = Vec::new();
765	    let mut seen = HashSet::new();
766	    for entry in corpus {
767	        if !vectors.contains_key(&entry.key) && seen.insert(entry.key) {
768	            fresh.push(entry.key);
769	            texts.push(entry.text.as_str());
770	        }
771	    }
772	    coverage.chunks = corpus.len();
773	    coverage.cached_chunks = corpus
774	        .iter()
775	        .filter(|entry| vectors.contains_key(&entry.key))
776	        .count();
777	    coverage.embedded_chunks = texts.len();
778	    if !texts.is_empty() {
779	        let embedded = embedder.embed_batch(&texts, EmbedKind::Passage)?;
780	        if embedded.len() != texts.len() {
781	            return Err(format!(
782	                "embedding count mismatch: {} chunks vs {} vectors",
783	                texts.len(),
784	                embedded.len()
785	            ));
786	        }
787	        for (key, vector) in fresh.iter().zip(embedded) {
788	            validate_vector(&vector, dims)?;
789	            vectors.insert(*key, vector);
790	        }
791	    }
792	    if let Some(store) = store
793	        && let Err(error) = store.save(namespace, dims, &fresh, &vectors, stored_rows, rebuild)
794	    {
795	        coverage.vector_cache_errors.push(error);
796	    }
797	    coverage.degraded |= !coverage.vector_cache_errors.is_empty();
798	    Ok(vectors)
799	}
