801	/// One file of a question's universe, read and cut.
802	enum FileRead {
803	    /// Unreadable, over [`MAX_FILE_BYTES`], binary or not UTF-8.
804	    Skipped,
805	    /// Blank.
806	    Empty,
807	    /// Its repository-relative path and its chunks ([`code_chunks`]), each
808	    /// with its BM25 document over the question's terms.
809	    Searched {
810	        path: String,
811	        chunks: Vec<(String, pixel_rank::Bm25Doc)>,
812	    },
813	}
814	
815	/// Read `file` (below `root`) and cut it into chunks, each counted over the
816	/// sorted query `terms` for the lexical channel. The embedded text and the
817	/// lexical document of a chunk are the same bytes, so the snippet shown for
818	/// a file is a chunk the lexical channel scored too.
819	fn read_file(root: &Path, file: &Path, terms: &[String]) -> FileRead {
820	    let Ok(bytes) = std::fs::read(file) else {
821	        return FileRead::Skipped;
822	    };
823	    if bytes.len() > MAX_FILE_BYTES || bytes.contains(&0) {
824	        return FileRead::Skipped;
825	    }
826	    let Ok(text) = String::from_utf8(bytes) else {
827	        return FileRead::Skipped;
828	    };
829	    if text.trim().is_empty() {
830	        return FileRead::Empty;
831	    }
832	    let path = file
833	        .strip_prefix(root)
834	        .unwrap_or(file)
835	        .to_string_lossy()
836	        .into_owned();
837	    // Filenames are evidence too, but directory names and language extensions
838	    // must not add shared noise or change ranks when the repository moves.
839	    // A filename can have compound extensions (`types.d.ts`): only the
840	    // basename before its first dot counts, so suffix components cannot
841	    // become lexical evidence.
842	    let stem = file.file_name().map_or_else(String::new, |name| {
843	        let basename = name.to_string_lossy();
844	        basename.split('.').next().unwrap_or_default().to_string()
845	    });
846	    let (stem_freqs, stem_len) = term_counts(&stem, terms);
847	    let chunks = code_chunks(&path, &text)
848	        .into_iter()
849	        .map(|(start, end)| {
850	            // Every chunk carries the filename stem's tokens, as if the name
851	            // were written once at its top.
852	            let (mut freqs, len) = term_counts(lexical_chunk(&text, start, end), terms);
853	            for (freq, stem_freq) in freqs.iter_mut().zip(&stem_freqs) {
854	                *freq += stem_freq;
855	            }
856	            let doc = pixel_rank::Bm25Doc {
857	                path: String::new(),
858	                term_freqs: freqs,
859	                len: len + stem_len,
860	            };
861	            (text[start..end].to_string(), doc)
862	        })
863	        .collect();
864	    FileRead::Searched { path, chunks }
865	}
866	
867	fn validate_vector(vector: &[f32], dims: usize) -> Result<(), String> {
868	    let norm: f64 = vector.iter().map(|x| f64::from(*x).powi(2)).sum();
869	    if dims == 0 || vector.len() != dims || !norm.is_finite() || norm <= 0.0 {
870	        return Err(
871	            "invalid embedding vector: expected finite, nonzero values with consistent dimensions"
872	                .into(),
873	        );
874	    }
875	    Ok(())
876	}
877	
878	/// Exclude identifier fragments created only by fixed byte-window boundaries
879	/// (the windows of an unparsed file or an oversize piece; symbol chunks end
880	/// on line boundaries).
881	fn lexical_chunk(text: &str, start: usize, end: usize) -> &str {
882	    let is_ident = |character: char| character.is_alphanumeric() || character == '_';
883	    let chunk = &text[start..end];
884	    let chunk = if text[..start].chars().next_back().is_some_and(&is_ident)
885	        && chunk.chars().next().is_some_and(&is_ident)
886	    {
887	        chunk
888	            .split_once(|character| !is_ident(character))
889	            .map_or("", |(_, complete)| complete)
890	    } else {
891	        chunk
892	    };
893	    if text[..end].chars().next_back().is_some_and(&is_ident)
894	        && text[end..].chars().next().is_some_and(&is_ident)
895	    {
896	        chunk
897	            .rsplit_once(|character| !is_ident(character))
898	            .map_or("", |(complete, _)| complete)
899	    } else {
900	        chunk
901	    }
902	}
903	
904	/// Preserve complete identifiers and split snake_case, camelCase and acronyms.
905	fn words(text: &str) -> HashSet<String> {
906	    let mut out = HashSet::new();
907	    for_each_word(text, |word| {
908	        out.insert(word);
909	    });
910	    out
911	}
912	
913	/// Every token [`words`] draws from `text`, lowercased, once per occurrence:
914	/// each identifier, then its snake_case, camelCase and acronym parts unless
915	/// the only part is the identifier itself (`readHTTPResponse` gives
916	/// `readhttpresponse`, `read`, `http`, `response`; `_setup` gives `_setup`,
917	/// `setup`; `setup` gives `setup` once).
918	fn for_each_word(text: &str, mut emit: impl FnMut(String)) {
919	    for word in text.split(|c: char| !c.is_alphanumeric() && c != '_') {
920	        if word.is_empty() {
921	            continue;
922	        }
923	        let mut parts = Vec::new();
924	        for part in word.split('_').filter(|s| !s.is_empty()) {
925	            let chars: Vec<(usize, char)> = part.char_indices().collect();
926	            let mut start = 0;
927	            for i in 1..chars.len() {
928	                let (_, prev) = chars[i - 1];
929	                let (offset, current) = chars[i];
930	                let next_lower = chars.get(i + 1).is_some_and(|(_, c)| c.is_lowercase());
931	                if (prev.is_lowercase() && current.is_uppercase())
932	                    || (prev.is_uppercase() && current.is_uppercase() && next_lower)
933	                {
934	                    parts.push(&part[start..offset]);
935	                    start = offset;
936	                }
937	            }
938	            parts.push(&part[start..]);
939	        }
940	        emit(word.to_lowercase());
941	        // A lone part equal to the identifier is that identifier again.
942	        if parts != [word] {
943	            for part in parts {
944	                emit(part.to_lowercase());
945	            }
946	        }
947	    }
948	}
949	
950	/// How often each of `terms` occurs among the tokens of `text` (aligned with
951	/// `terms`), and the token count: one BM25 document.
952	fn term_counts(text: &str, terms: &[String]) -> (Vec<u32>, u32) {
953	    let mut freqs = vec![0u32; terms.len()];
954	    let mut len = 0u32;
955	    for_each_word(text, |word| {
956	        len += 1;
957	        if let Ok(index) = terms.binary_search(&word) {
958	            freqs[index] += 1;
959	        }
960	    });
961	    (freqs, len)
962	}
