964	/// [`query_terms`], sorted: the term order of every lexical document.
965	fn sorted_query_terms(query: &str) -> Vec<String> {
966	    let mut terms: Vec<String> = query_terms(query).into_iter().collect();
967	    terms.sort_unstable();
968	    terms
969	}
