971	fn query_terms(query: &str) -> HashSet<String> {
972	    // Do not impose a minimum length: x, id, io and negation carry meaning.
973	    let normalized = query.replace("n’t", " not").replace("n't", " not");
974	    words(&normalized)
975	        .into_iter()
976	        .filter(|w| {
977	            !matches!(
978	                w.as_str(),
979	                "a" | "an"
980	                    | "the"
981	                    | "is"
982	                    | "are"
983	                    | "was"
984	                    | "were"
985	                    | "be"
986	                    | "been"
987	                    | "being"
988	                    | "do"
989	                    | "does"
990	                    | "did"
991	                    | "how"
992	                    | "what"
993	                    | "where"
994	                    | "when"
995	                    | "which"
996	                    | "who"
997	                    | "why"
998	                    | "can"
999	                    | "could"
1000	                    | "would"
