1032	/// Each file of `files` with its [`Lexical`] evidence, from the term counts
1033	/// of its chunks (`chunks`: the index of the chunk's file in `files`, and
1034	/// the chunk as a BM25 document over `terms`).
1035	///
1036	/// A chunk, not a file, is the BM25 document: the terms must meet in one
1037	/// place of the file to count together, as the distinct-term coverage this
1038	/// replaced required, and the document frequency behind each term's IDF is
1039	/// taken over every chunk of the searched universe. The file keeps its best
1040	/// chunk's score.
1041	fn lexical_evidence(
1042	    terms: &[String],
1043	    files: Vec<String>,
1044	    chunks: Vec<(usize, pixel_rank::Bm25Doc)>,
1045	) -> HashMap<String, Lexical> {
1046	    let mut evidence = vec![Lexical::default(); files.len()];
1047	    let (owners, docs): (Vec<usize>, Vec<pixel_rank::Bm25Doc>) = chunks.into_iter().unzip();
1048	    let scores = pixel_rank::bm25_scores(terms, &docs).unwrap_or_else(|| vec![0.0; docs.len()]);
1049	    for ((file, doc), score) in owners.into_iter().zip(&docs).zip(scores) {
1050	        let found = &mut evidence[file];
1051	        found.score = found.score.max(score);
1052	        let matches = doc.term_freqs.iter().filter(|freq| **freq > 0).count();
1053	        found.matches = found.matches.max(matches);
1054	    }
1055	    files.into_iter().zip(evidence).collect()
1056	}
