1058	/// A file's lexical evidence for one question.
1059	#[derive(Clone, Copy, Debug, Default, PartialEq)]
1060	struct Lexical {
1061	    /// BM25 score of its best chunk (0 when no query term occurs).
1062	    score: f64,
1063	    /// Most distinct query terms found together in one chunk.
1064	    matches: usize,
1065	}
