1067	/// Kinds of file that answer a question about code less often than the code
1068	/// they test, configure or describe, and rank below it unless the question
1069	/// names the kind ([`FileKind::named_by`]).
1070	#[derive(Clone, Copy, Debug, PartialEq, Eq)]
1071	pub enum FileKind {
1072	    /// A test or spec: under `test/`, `__tests__/`, `spec/` or `specs/`, or named
1073	    /// `*_test.*`, `*.test.*`, `*.spec.*` or `*_spec.*`.
1074	    Test,
1075	    /// Configuration or data: `json`, `yaml`/`yml`, `toml`, or anything under
1076	    /// `locales/`, `locale/` or `i18n/`.
1077	    Config,
1078	    /// Prose documentation: `md`.
1079	    Docs,
1080	}
1081	
1082	impl FileKind {
1083	    /// The kind of the file at the repository-relative `path`, `None` for code.
1084	    /// Test comes first: a JSON fixture under `spec/` is a test file.
1085	    fn of(path: &str) -> Option<Self> {
1086	        let path = path.to_lowercase();
1087	        let (dirs, name) = path.rsplit_once('/').unwrap_or(("", &path));
1088	        let mut dirs = dirs.split('/');
1089	        let ext = name.rsplit_once('.').map_or("", |(_, ext)| ext);
1090	        if dirs
1091	            .clone()
1092	            .any(|dir| matches!(dir, "test" | "__tests__" | "spec" | "specs"))
1093	            || ["_test.", ".test.", ".spec.", "_spec."]
1094	                .iter()
1095	                .any(|marker| name.contains(marker))
1096	        {
1097	            Some(Self::Test)
1098	        } else if matches!(ext, "json" | "yaml" | "yml" | "toml")
1099	            || dirs.any(|dir| matches!(dir, "locales" | "locale" | "i18n"))
1100	        {
1101	            Some(Self::Config)
1102	        } else if ext == "md" {
1103	            Some(Self::Docs)
1104	        } else {
1105	            None
1106	        }
1107	    }
1108	
1109	    /// Whether a question with the query `terms` asks for this kind of file,
1110	    /// which then ranks on its evidence alone.
1111	    fn named_by(self, terms: &[String]) -> bool {
1112	        terms.iter().any(|term| {
1113	            let term = term.as_str();
1114	            match self {
1115	                Self::Test => matches!(term, "test" | "tests" | "testing" | "spec" | "specs"),
1116	                Self::Config => matches!(
1117	                    term,
1118	                    "config"
1119	                        | "configs"
1120	                        | "configuration"
1121	                        | "settings"
1122	                        | "json"
1123	                        | "yaml"
1124	                        | "yml"
1125	                        | "toml"
1126	                        | "locale"
1127	                        | "locales"
1128	                        | "translation"
1129	                        | "translations"
1130	                        | "i18n"
1131	                ),
1132	                Self::Docs => matches!(
1133	                    term,
1134	                    "readme" | "doc" | "docs" | "documentation" | "markdown" | "md" | "changelog"
1135	                ),
1136	            }
1137	        })
1138	    }
1139	
1140	    /// The name JSON hits carry in `demoted`.
1141	    pub fn as_str(self) -> &'static str {
1142	        match self {
1143	            Self::Test => "test",
1144	            Self::Config => "config",
1145	            Self::Docs => "docs",
1146	        }
1147	    }
1148	}
