1150	/// Factor on the fused score of a [`FileKind`] file the question does not
1151	/// name: it keeps its place among its peers and still ranks when its
1152	/// evidence is strong, but a source file with the same evidence goes first.
1153	const DEMOTED_WEIGHT: f64 = 0.8;
1154	
1155	fn rank_files(
1156	    query: &str,
1157	    lexical: &HashMap<String, Lexical>,
1158	    best: HashMap<String, f32>,
1159	    mut snippets: HashMap<String, String>,
1160	    k: usize,
1161	) -> Vec<AskHit> {
1162	    let terms = sorted_query_terms(query);
1163	    let lexical_ranks = competition_ranks(
1164	        lexical
1165	            .values()
1166	            .map(|evidence| pixel_rank::bm25_fixed(evidence.score)),
1167	    );
1168	    let mut semantic: Vec<_> = best.into_iter().collect();
1169	    semantic.sort_by(|a, b| b.1.total_cmp(&a.1).then(a.0.cmp(&b.0)));
1170	    let mut hits: Vec<_> = semantic
1171	        .into_iter()
1172	        .enumerate()
1173	        .map(|(index, (path, score))| {
1174	            let evidence = lexical.get(&path).copied().unwrap_or_default();
1175	            let fixed = pixel_rank::bm25_fixed(evidence.score);
1176	            // Competition ranks: equal scores receive exactly equal evidence weight.
1177	            let fused = 2.0 / (60.0 + (index + 1) as f64)
1178	                + if fixed == 0 {
1179	                    0.0
1180	                } else {
1181	                    lexical_ranks
1182	                        .get(&fixed)
1183	                        .map_or(0.0, |&rank| 1.0 / (60.0 + rank as f64))
1184	                };
1185	            let demoted = FileKind::of(&path).filter(|kind| !kind.named_by(&terms));
1186	            AskHit {
1187	                snippet: snippets.remove(&path).unwrap_or_default(),
1188	                path,
1189	                score,
1190	                semantic_score: score,
1191	                ranking_score: if demoted.is_some() {
1192	                    fused * DEMOTED_WEIGHT
1193	                } else {
1194	                    fused
1195	                },
1196	                lexical_matches: evidence.matches,
1197	                lexical_score: evidence.score,
1198	                demoted,
1199	                query_terms: terms.len(),
1200	            }
1201	        })
1202	        .collect();
1203	    hits.sort_by(|a, b| {
1204	        b.ranking_score
1205	            .total_cmp(&a.ranking_score)
1206	            .then(a.path.cmp(&b.path))
1207	    });
1208	    hits.truncate(k);
1209	    hits
1210	}
