1212	/// The competition rank of every value in `values`: one plus the number of
1213	/// values strictly greater, so equal values share a rank and the next value
1214	/// skips the tied ones (5, 3, 3, 1 rank 1, 2, 2, 4). One pass over a
1215	/// histogram of the values: a scan of every file per ranked file cost 4 s at
1216	/// the 50 000-file ceiling.
1217	fn competition_ranks<T: Ord + std::hash::Hash + Copy>(
1218	    values: impl Iterator<Item = T>,
1219	) -> HashMap<T, usize> {
1220	    let mut counts = BTreeMap::new();
1221	    for value in values {
1222	        *counts.entry(value).or_insert(0usize) += 1;
1223	    }
1224	    let mut ranks = HashMap::with_capacity(counts.len());
1225	    let mut above = 0;
1226	    for (value, count) in counts.into_iter().rev() {
1227	        ranks.insert(value, 1 + above);
1228	        above += count;
1229	    }
1230	    ranks
1231	}
1232	
1233	fn make_snippet(text: &str) -> String {
1234	    let joined: String = text.split_whitespace().collect::<Vec<_>>().join(" ");
1235	    let mut cut = joined;
1236	    if cut.len() > 160 {
1237	        // Truncate at a char boundary to avoid a multi-byte-char panic.
1238	        let mut boundary = 160;
1239	        while boundary > 0 && !cut.is_char_boundary(boundary) {
1240	            boundary -= 1;
1241	        }
1242	        cut.truncate(boundary);
1243	        cut.push('…');
1244	    }
1245	    cut
1246	}
