1841	    /// Every file of `tree` (relative path, content) asked `query` through
1842	    /// the production ranking, with a model that scores every chunk alike:
1843	    /// the semantic channel then orders by path, so only the lexical channel
1844	    /// and the file-kind weight can move a file.
1845	    fn ask_tree(tree: &[(&str, &str)], query: &str) -> Vec<AskHit> {
1846	        let dir = tempfile::tempdir().unwrap();
1847	        for (path, text) in tree {
1848	            write(dir.path(), path, text);
1849	        }
1850	        let (files, coverage) = collect_files(dir.path(), None);
1851	        ask_collected(
1852	            dir.path(),
1853	            query,
1854	            usize::MAX,
1855	            files,
1856	            coverage,
1857	            &mut FixtureEmbedder { fail: false },
1858	            None,
1859	        )
1860	        .unwrap()
1861	        .hits
1862	    }
