1864	    fn found<'a>(hits: &'a [AskHit], path: &str) -> &'a AskHit {
1865	        hits.iter().find(|hit| hit.path == path).unwrap()
1866	    }
1867	
1868	    fn position(hits: &[AskHit], path: &str) -> usize {
1869	        hits.iter().position(|hit| hit.path == path).unwrap()
1870	    }
