1872	    /// IDF: a term most files carry says little, a term one file carries
1873	    /// says a lot. `a_noisy.rs` repeats the common term forty times,
1874	    /// `b_rare.rs` names the rare one once; the distinct-term count this
1875	    /// replaced tied them (one term each, both lexical rank 1), BM25 gives
1876	    /// the rare file rank 1 and the noisy file rank 2, exactly.
1877	    #[test]
1878	    fn rare_term_file_beats_a_file_repeating_a_common_term() {
1879	        let noisy = "fn handler() {}\n".repeat(40);
1880	        let hits = ask_tree(
1881	            &[
1882	                ("a_noisy.rs", &noisy),
1883	                ("b_rare.rs", "fn settle_ledger() {}"),
1884	                ("c.rs", "fn handler() {}"),
1885	                ("d.rs", "fn handler() {}"),
1886	                ("e.rs", "fn handler() {}"),
1887	            ],
1888	            "ledger handler",
1889	        );
1890	        let (noisy, rare) = (found(&hits, "a_noisy.rs"), found(&hits, "b_rare.rs"));
1891	        assert_eq!((noisy.lexical_matches, rare.lexical_matches), (1, 1));
1892	        assert!(rare.lexical_score > noisy.lexical_score);
1893	        // Path order puts the noisy file first semantically (tied cosine);
1894	        // lexically the rare file is first and the noisy one second.
1895	        assert_eq!(
1896	            rare.ranking_score.to_bits(),
1897	            (2.0 / 62.0 + 1.0 / 61.0_f64).to_bits()
1898	        );
1899	        assert_eq!(
1900	            noisy.ranking_score.to_bits(),
1901	            (2.0 / 61.0 + 1.0 / 62.0_f64).to_bits()
1902	        );
1903	        let common = found(&hits, "c.rs").lexical_score;
1904	        assert!(noisy.lexical_score > common, "tf still counts, saturated");
1905	        assert!(
1906	            noisy.lexical_score < 2.0 * common,
1907	            "forty occurrences must not weigh forty times one: {} vs {common}",
1908	            noisy.lexical_score
1909	        );
1910	    }
