1	//! Content-addressed store of the chunk vectors `pixel search-meaning` embeds.
2	//!
3	//! Lives under `<root>/.pixel/code-vectors/` of an indexed repository (the
4	//! caller decides when: [`crate::code_search::vector_cache_for`]) so a warm
5	//! question pays the model only for the chunks whose text changed. A vector is
6	//! found by the xxh3-128 hash of its chunk text, seeded by a [`Namespace`]
7	//! naming the model, its embedder revision and the chunker version, and it is
8	//! stored as the embedder returned it: `f32`, never quantized, so a cached
9	//! question ranks bit for bit like an uncached one.
10	//!
11	//! Layout:
12	//!
13	//! ```text
14	//! lock                     flock(2): shared while reading, exclusive around every read-modify-write
15	//! manifest.json            the one list of live segments, replaced by tmp + fsync + rename
16	//! seg-<xxh3-128 hex>.vec   immutable segments, named by the hash of their bytes
17	//! ```
18	//!
19	//! Segment (little-endian): `b"PXCVEC01"` | dim `u32` | rows `u64` |
20	//! rows × (key `u128` | dim × `f32`).
21	//!
22	//! A reader never sees a partial write: segments and the manifest appear by
23	//! rename only, and compaction deletes a segment under the exclusive lock that
24	//! readers' shared lock excludes. A segment the manifest names but that is
25	//! missing, truncated or altered is an error the caller reports, never a
26	//! silent skip; the next write rebuilds the store from the vectors in hand.
27	
28	use std::collections::{HashMap, HashSet};
29	use std::fs::{self, File, OpenOptions};
30	use std::io::Write;
31	use std::path::{Path, PathBuf};
32	
33	use serde::{Deserialize, Serialize};
34	
35	/// Directory of the store under `.pixel/`.
36	pub const DIR: &str = "code-vectors";
37	const MANIFEST: &str = "manifest.json";
38	const LOCK: &str = "lock";
39	const MAGIC: &[u8; 8] = b"PXCVEC01";
40	/// Magic (8) + dim (4) + rows (8).
41	const HEADER_LEN: usize = 20;
42	const MANIFEST_VERSION: u32 = 1;
43	
44	/// Key of one chunk's vector.
45	pub(crate) type ChunkKey = u128;
46	
47	/// What a stored vector depends on besides its chunk text: the model, the
48	/// revision of the library that runs it, and the chunker that cut the text.
49	/// A change of any of them changes every key and every segment's namespace,
50	/// so no vector of another namespace is ever served.
51	pub(crate) struct Namespace {
52	    name: String,
53	    seed: u64,
54	}
55	
56	impl Namespace {
57	    pub(crate) fn new(model_id: &str, revision: u32, chunker: u32) -> Self {
58	        let name = format!("{model_id}@r{revision}+c{chunker}");
59	        let seed = xxhash_rust::xxh3::xxh3_64(name.as_bytes());
60	        Self { name, seed }
61	    }
62	
63	    /// The key of `text`'s vector: xxh3-128 of its bytes, seeded by the
64	    /// namespace.
65	    pub(crate) fn key(&self, text: &str) -> ChunkKey {
66	        xxhash_rust::xxh3::xxh3_128_with_seed(text.as_bytes(), self.seed)
67	    }
68	}
69	
70	#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
71	struct SegmentEntry {
72	    file: String,
73	    namespace: String,
74	    dim: usize,
75	    rows: usize,
76	}
77	
78	#[derive(Debug, Serialize, Deserialize)]
79	struct Manifest {
80	    version: u32,
81	    segments: Vec<SegmentEntry>,
82	}
83	
84	impl Manifest {
85	    fn new(segments: Vec<SegmentEntry>) -> Self {
86	        Self {
87	            version: MANIFEST_VERSION,
88	            segments,
89	        }
90	    }
91	
92	    /// Rows every segment holds, whatever its namespace.
93	    fn rows(&self) -> usize {
94	        self.segments.iter().map(|segment| segment.rows).sum()
95	    }
96	}
97	
98	/// What [`Store::load`] found for one question.
99	#[derive(Debug, Default)]
100	pub(crate) struct Loaded {
101	    /// The wanted keys the store holds, with their vectors.
102	    pub vectors: HashMap<ChunkKey, Vec<f32>>,
103	    /// Rows the manifest names across every namespace: live, unreachable and
104	    /// duplicate alike.
105	    pub stored_rows: usize,
106	    /// Why part of the store could not be read; empty when all of it was.
107	    pub errors: Vec<String>,
108	}
109	
110	/// Handle on one store directory; cheap, holds no open file.
111	#[derive(Debug, Clone)]
112	pub(crate) struct Store {
113	    dir: PathBuf,
114	}
115	
116	/// Whether the store holds enough unreachable rows to be rewritten with the
117	/// live ones only: more than a quarter of the live rows (unreachable above a
118	/// fifth of the file). Below that, an edit only appends its changed chunks.
119	fn needs_compaction(stored_rows: usize, live_rows: usize) -> bool {
120	    stored_rows.saturating_sub(live_rows) > live_rows / 4
121	}
122	
123	impl Store {
124	    pub(crate) fn at(dir: &Path) -> Self {
125	        Self {
126	            dir: dir.to_path_buf(),
127	        }
128	    }
129	
130	    /// The vectors of `wanted` stored under `namespace` at `dim`, read under
131	    /// the shared lock. A store never written is empty without an error;
132	    /// every unreadable part of one is named in `errors`, and the vectors of
133	    /// the healthy segments are still returned.
134	    pub(crate) fn load(
135	        &self,
136	        namespace: &Namespace,
137	        dim: usize,
138	        wanted: &HashSet<ChunkKey>,
139	    ) -> Loaded {
140	        let mut loaded = Loaded::default();
141	        if !self.dir.join(MANIFEST).exists() {
142	            return loaded;
143	        }
144	        let _lock = match self.lock(false) {
145	            Ok(lock) => lock,
146	            Err(error) => {
147	                loaded.errors.push(error);
148	                return loaded;
149	            }
150	        };
151	        let manifest = match self.read_manifest() {
152	            Ok(Some(manifest)) => manifest,
153	            Ok(None) => return loaded,
154	            Err(error) => {
155	                loaded.errors.push(error);
156	                return loaded;
157	            }
158	        };
159	        loaded.stored_rows = manifest.rows();
160	        for entry in &manifest.segments {
161	            if entry.namespace != namespace.name || entry.dim != dim {
162	                continue;
163	            }
164	            if let Err(error) = read_segment(&self.dir, entry, wanted, &mut loaded.vectors) {
165	                loaded.errors.push(error);
166	            }
167	        }
168	        loaded
169	    }
170	
171	    /// Record a question's vectors: `fresh` (just embedded) is appended as
172	    /// one segment, or the whole store is rewritten with `live` (every
173	    /// vector of the question's universe) when `rebuild` asks for it (its
174	    /// load failed) or unreachable rows passed [`needs_compaction`], counted
175	    /// from the `stored_rows` the load saw. Nothing is written when there is
176	    /// nothing new, nothing to repair and nothing to collect. Returns whether
177	    /// the store was written.
178	    ///
179	    /// # Errors
180	    ///
181	    /// Any I/O failure; the store is left as it was, since the manifest is
182	    /// replaced last.
183	    pub(crate) fn save(
184	        &self,
185	        namespace: &Namespace,
186	        dim: usize,
187	        fresh: &[ChunkKey],
188	        live: &HashMap<ChunkKey, Vec<f32>>,
189	        stored_rows: usize,
190	        rebuild: bool,
191	    ) -> Result<bool, String> {
192	        if fresh.is_empty() && !rebuild && !needs_compaction(stored_rows, live.len()) {
193	            return Ok(false);
194	        }
195	        self.commit_with(namespace, dim, fresh, live, rebuild, &mut || {})?;
196	        Ok(true)
197	    }
198	
199	    /// [`Store::save`]'s write, under the exclusive lock, with `between`
200	    /// called after the manifest was read and before it is replaced (the
201	    /// window a lost update would need).
202	    fn commit_with(
203	        &self,
204	        namespace: &Namespace,
205	        dim: usize,
206	        fresh: &[ChunkKey],
207	        live: &HashMap<ChunkKey, Vec<f32>>,
208	        rebuild: bool,
209	        between: &mut dyn FnMut(),
210	    ) -> Result<(), String> {
211	        fs::create_dir_all(&self.dir)
212	            .map_err(|e| format!("code-vector store {}: {e}", self.dir.display()))?;
213	        let _lock = self.lock(true)?;
214	        // An unreadable manifest is rebuilt from the vectors in hand, like
215	        // a store whose load failed.
216	        let current = if rebuild {
217	            None
218	        } else {
219	            self.read_manifest()
220	                .ok()
221	                .map(|manifest| manifest.unwrap_or_else(|| Manifest::new(Vec::new())))
222	        };
223	        between();
224	        let next = match current {
225	            Some(mut manifest) if !needs_compaction(manifest.rows() + fresh.len(), live.len()) => {
226	                if let Some(entry) = self.write_segment(namespace, dim, fresh, live)?
227	                    && !manifest.segments.contains(&entry)
228	                {
229	                    manifest.segments.push(entry);
230	                }
231	                manifest
232	            }
233	            _ => {
234	                let mut keys: Vec<ChunkKey> = live.keys().copied().collect();
235	                keys.sort_unstable();
236	                Manifest::new(
237	                    self.write_segment(namespace, dim, &keys, live)?
238	                        .into_iter()
239	                        .collect(),
240	                )
241	            }
242	        };
243	        let bytes = serde_json::to_vec(&next).expect("a manifest always serializes");
244	        write_atomically(&self.dir, MANIFEST, &bytes)?;
245	        self.remove_unlisted(&next);
246	        Ok(())
247	    }
248	
249	    /// The lock file, locked shared or `exclusive`; released when dropped.
250	    fn lock(&self, exclusive: bool) -> Result<File, String> {
251	        let path = self.dir.join(LOCK);
252	        let file = OpenOptions::new()
253	            .read(true)
254	            .write(true)
255	            .create(true)
256	            .truncate(false)
257	            .open(&path)
258	            .map_err(|e| format!("code-vector lock {}: {e}", path.display()))?;
259	        if exclusive {
260	            file.lock()
261	        } else {
262	            file.lock_shared()
263	        }
264	        .map_err(|e| format!("code-vector lock {}: {e}", path.display()))?;
265	        Ok(file)
266	    }
267	
268	    /// The manifest, `None` when the store has none yet.
269	    fn read_manifest(&self) -> Result<Option<Manifest>, String> {
270	        let path = self.dir.join(MANIFEST);
271	        let bytes = match fs::read(&path) {
272	            Ok(bytes) => bytes,
273	            Err(error) if error.kind() == std::io::ErrorKind::NotFound => return Ok(None),
274	            Err(error) => return Err(format!("code-vector manifest {}: {error}", path.display())),
275	        };
276	        let manifest: Manifest = serde_json::from_slice(&bytes)
277	            .map_err(|e| format!("code-vector manifest {} is corrupt: {e}", path.display()))?;
278	        if manifest.version != MANIFEST_VERSION {
279	            return Err(format!(
280	                "code-vector manifest {} has version {}, this pixel reads {MANIFEST_VERSION}",
281	                path.display(),
282	                manifest.version
283	            ));
284	        }
285	        Ok(Some(manifest))
286	    }
287	
288	    /// Write `keys`' vectors as one immutable segment; `None` for no key.
289	    fn write_segment(
290	        &self,
291	        namespace: &Namespace,
292	        dim: usize,
293	        keys: &[ChunkKey],
294	        vectors: &HashMap<ChunkKey, Vec<f32>>,
295	    ) -> Result<Option<SegmentEntry>, String> {
296	        if keys.is_empty() {
297	            return Ok(None);
298	        }
299	        let mut bytes = Vec::with_capacity(HEADER_LEN + keys.len() * row_len(dim));
300	        bytes.extend_from_slice(&segment_header(dim, keys.len()));
301	        for key in keys {
302	            let vector = &vectors[key];
303	            assert_eq!(vector.len(), dim, "a stored vector has the store's dim");
304	            bytes.extend_from_slice(&key.to_le_bytes());
305	            for value in vector {
306	                bytes.extend_from_slice(&value.to_le_bytes());
307	            }
308	        }
309	        let file = segment_file_name(&bytes);
310	        write_atomically(&self.dir, &file, &bytes)?;
311	        Ok(Some(SegmentEntry {
312	            file,
313	            namespace: namespace.name.clone(),
314	            dim,
315	            rows: keys.len(),
316	        }))
317	    }
318	
319	    /// Delete the segments `manifest` does not name and the temporary files
320	    /// of an interrupted write. Called under the exclusive lock, which every
321	    /// writer holds while it creates files, so nothing in flight is removed.
322	    /// A file that cannot be removed only costs disk until the next write.
323	    fn remove_unlisted(&self, manifest: &Manifest) {
324	        let Ok(entries) = fs::read_dir(&self.dir) else {
325	            return;
326	        };
327	        let listed: HashSet<&str> = manifest
328	            .segments
329	            .iter()
330	            .map(|segment| segment.file.as_str())
331	            .collect();
332	        for entry in entries.flatten() {
333	            let name = entry.file_name();
334	            let name = name.to_string_lossy();
335	            let segment = name
336	                .strip_prefix("seg-")
337	                .and_then(|rest| rest.strip_suffix(".vec"))
338	                .is_some();
339	            if (segment && !listed.contains(name.as_ref())) || name.ends_with(".tmp") {
340	                let _ = fs::remove_file(entry.path());
341	            }
342	        }
343	    }
344	
345	    /// Every key of every segment file present, listed or not.
346	    #[cfg(test)]
347	    pub(crate) fn keys_on_disk(&self) -> Vec<ChunkKey> {
348	        let mut keys = Vec::new();
349	        for entry in fs::read_dir(&self.dir).unwrap().flatten() {
350	            let name = entry.file_name().to_string_lossy().into_owned();
351	            if !name.starts_with("seg-") {
352	                continue;
353	            }
354	            let bytes = fs::read(entry.path()).unwrap();
355	            let dim = u32::from_le_bytes(bytes[8..12].try_into().unwrap()) as usize;
356	            for row in bytes[HEADER_LEN..].chunks_exact(row_len(dim)) {
357	                keys.push(u128::from_le_bytes(row[..16].try_into().unwrap()));
358	            }
359	        }
360	        keys.sort_unstable();
361	        keys
362	    }
363	}
364	
365	fn row_len(dim: usize) -> usize {
366	    16 + 4 * dim
367	}
368	
369	fn segment_header(dim: usize, rows: usize) -> [u8; HEADER_LEN] {
370	    let mut header = [0u8; HEADER_LEN];
371	    header[..8].copy_from_slice(MAGIC);
372	    header[8..12].copy_from_slice(&u32::try_from(dim).unwrap_or(u32::MAX).to_le_bytes());
373	    header[12..].copy_from_slice(&(rows as u64).to_le_bytes());
374	    header
375	}
376	
377	fn segment_file_name(bytes: &[u8]) -> String {
378	    format!("seg-{:032x}.vec", xxhash_rust::xxh3::xxh3_128(bytes))
379	}
380	
381	/// Add the vectors of `wanted` keys held by the segment `entry` names to
382	/// `out`, after checking the file is exactly the one the manifest names: its
383	/// header announces the entry's dim and rows, and its bytes hash to its name
384	/// (so a truncated or altered file is refused, and the length follows).
385	fn read_segment(
386	    dir: &Path,
387	    entry: &SegmentEntry,
388	    wanted: &HashSet<ChunkKey>,
389	    out: &mut HashMap<ChunkKey, Vec<f32>>,
390	) -> Result<(), String> {
391	    let bytes = fs::read(dir.join(&entry.file)).map_err(|e| {
392	        format!(
393	            "code-vector segment {} named by the manifest is unreadable: {e}",
394	            entry.file
395	        )
396	    })?;
397	    if !bytes.starts_with(&segment_header(entry.dim, entry.rows))
398	        || segment_file_name(&bytes) != entry.file
399	    {
400	        return Err(format!(
401	            "code-vector segment {} does not match the manifest (truncated or altered)",
402	            entry.file
403	        ));
404	    }
405	    for row in bytes[HEADER_LEN..].chunks_exact(row_len(entry.dim)) {
406	        let key = u128::from_le_bytes(row[..16].try_into().expect("a row opens on a 16-byte key"));
407	        if wanted.contains(&key) {
408	            let vector = row[16..]
409	                .as_chunks::<4>()
410	                .0
411	                .iter()
412	                .map(|value| f32::from_le_bytes(*value))
413	                .collect();
414	            out.insert(key, vector);
415	        }
416	    }
417	    Ok(())
418	}
419	
420	/// Write `bytes` to `dir/name` so no reader ever sees a partial file: a
421	/// temporary file in the same directory, fsynced, then renamed over the name.
422	fn write_atomically(dir: &Path, name: &str, bytes: &[u8]) -> Result<(), String> {
423	    let tmp = dir.join(format!(".{name}.{}.tmp", std::process::id()));
424	    let target = dir.join(name);
425	    let written = File::create(&tmp).and_then(|mut file| {
426	        file.write_all(bytes)?;
427	        file.sync_all()
428	    });
429	    if let Err(error) = written.and_then(|()| fs::rename(&tmp, &target)) {
430	        let _ = fs::remove_file(&tmp);
431	        return Err(format!("code-vector store {}: {error}", target.display()));
432	    }
433	    // The rename is durable once the directory is; best effort where the
434	    // platform refuses to fsync a directory.
435	    if let Ok(directory) = File::open(dir) {
436	        let _ = directory.sync_all();
437	    }
438	    Ok(())
439	}
