469	    /// The compaction boundary: unreachable rows exactly at a quarter of
470	    /// the live rows are kept, one more triggers the rewrite.
471	    #[test]
472	    fn needs_compaction_should_start_strictly_above_a_quarter_of_the_live_rows() {
473	        assert!(!needs_compaction(4, 4), "nothing unreachable");
474	        assert!(!needs_compaction(5, 4), "exactly a quarter: kept");
475	        assert!(needs_compaction(6, 4), "above a quarter: rewritten");
476	        assert!(!needs_compaction(100, 80), "20 of 80 is a quarter");
477	        assert!(needs_compaction(101, 80));
478	        assert!(!needs_compaction(3, 4), "fewer stored than live");
