499	    fn save_then_load_should_return_the_exact_vectors_of_the_wanted_keys_only() {
500	        let (_dir, store) = store();
501	        let loaded = store.load(&namespace(), 2, &all(&[1]));
502	        assert!(loaded.vectors.is_empty() && loaded.errors.is_empty());
503	        assert!(!store.dir.exists(), "a load writes nothing");
504	        let vectors = HashMap::from([(1, vec![0.1f32, -2.5e-8]), (2, vec![3.0, 4.0])]);
505	        assert!(
506	            store
507	                .save(&namespace(), 2, &[1, 2], &vectors, 0, false)
508	                .unwrap()
