589	    /// Two writers racing on the same store: the second one runs its whole
590	    /// write while the first sits between reading and replacing the
591	    /// manifest. The lock makes it wait, so the store ends with both sets;
592	    /// without the lock the first writer's stale manifest drops the second
593	    /// writer's segment.
594	    #[test]
595	    fn concurrent_writers_should_leave_a_store_holding_both_sets() {
596	        let (_dir, store) = store();
597	        let store = &store;
598	        let union = &live(&[1, 2, 3, 11, 12, 13]);
599	        let (read_tx, read_rx) = std::sync::mpsc::channel();
600	        let (done_tx, done_rx) = std::sync::mpsc::channel::<()>();
601	        std::thread::scope(|scope| {
602	            let first = scope.spawn(move || {
603	                store.commit_with(&namespace(), 2, &[1, 2, 3], union, false, &mut || {
604	                    read_tx.send(()).unwrap();
605	                    // Long enough for an unlocked second writer to finish.
606	                    let _ = done_rx.recv_timeout(std::time::Duration::from_secs(1));
607	                })
608	            });
609	            read_rx.recv().unwrap();
610	            store
611	                .commit_with(&namespace(), 2, &[11, 12, 13], union, false, &mut || {})
612	                .unwrap();
613	            let _ = done_tx.send(());
614	            first.join().unwrap().unwrap();
615	        });
616	        let loaded = store.load(&namespace(), 2, &all(&[1, 2, 3, 11, 12, 13]));
617	        assert_eq!(&loaded.vectors, union);
618	        assert!(loaded.errors.is_empty(), "{:?}", loaded.errors);
619	        assert_eq!(manifest(store).rows(), 6);
620	    }
