622	    /// A segment the manifest names is missing, truncated, altered, or
623	    /// described by a wrong entry: each is an error naming the file, the
624	    /// healthy segments still answer, and the next save rebuilds the store.
625	    #[test]
626	    fn damaged_segments_should_be_errors_and_rebuilt_never_skipped() {
627	        /// Damages the segment `file` and returns the name the error must carry.
628	        type Damage = fn(&Store, &str) -> String;
629	        let damages: [(&str, Damage); 4] = [
630	            ("missing", |store, file| {
631	                fs::remove_file(store.dir.join(file)).unwrap();
632	                file.to_string()
633	            }),
634	            ("truncated", |store, file| {
635	                let path = store.dir.join(file);
636	                let bytes = fs::read(&path).unwrap();
637	                fs::write(&path, &bytes[..bytes.len() - 1]).unwrap();
638	                file.to_string()
639	            }),
640	            ("altered", |store, file| {
641	                let path = store.dir.join(file);
642	                let mut bytes = fs::read(&path).unwrap();
643	                *bytes.last_mut().unwrap() ^= 1;
644	                fs::write(&path, bytes).unwrap();
645	                file.to_string()
646	            }),
647	            ("wrong entry", |store, file| {
648	                // An intact file of another shape and the same byte length:
649	                // 1 row × (16 + 4·20) = 2 rows × (16 + 4·8). Only the
650	                // header tells it from the two rows the entry announces.
651	                let other = HashMap::from([(4, vec![4.0; 20])]);
652	                let written = store
653	                    .write_segment(&namespace(), 20, &[4], &other)
654	                    .unwrap()
655	                    .unwrap();
656	                let mut manifest = manifest(store);
657	                let entry = manifest
658	                    .segments
659	                    .iter_mut()
660	                    .find(|entry| entry.file == file)
661	                    .unwrap();
662	                assert_eq!((entry.rows, entry.dim), (2, 8));
663	                entry.file.clone_from(&written.file);
664	                let bytes = serde_json::to_vec(&manifest).unwrap();
665	                write_atomically(&store.dir, MANIFEST, &bytes).unwrap();
666	                written.file
667	            }),
668	        ];
669	        for (label, damage) in damages {
670	            let (_dir, store) = store();
671	            let ns = namespace();
672	            let vectors: HashMap<ChunkKey, Vec<f32>> =
673	                [1, 2, 3].map(|key| (key, vec![key as f32; 8])).into();
674	            store
675	                .commit_with(&ns, 8, &[1], &vectors, false, &mut || {})
676	                .unwrap();
677	            store
678	                .commit_with(&ns, 8, &[2, 3], &vectors, false, &mut || {})
679	                .unwrap();
680	            let listed = manifest(&store).segments[1].file.clone();
681	            let damaged = damage(&store, &listed);
682	            let loaded = store.load(&ns, 8, &all(&[1, 2, 3]));
683	            assert_eq!(loaded.errors.len(), 1, "{label}: {:?}", loaded.errors);
684	            assert!(
685	                loaded.errors[0].contains(&damaged),
686	                "{label}: {:?}",
687	                loaded.errors
688	            );
689	            assert_eq!(
690	                loaded.vectors.keys().copied().collect::<Vec<_>>(),
691	                [1],
692	                "{label}: the healthy segment still answers"
693	            );
694	            let rebuild = !loaded.errors.is_empty();
695	            assert!(
696	                store
697	                    .save(&ns, 8, &[], &vectors, loaded.stored_rows, rebuild)
698	                    .unwrap(),
699	                "{label}"
700	            );
701	            let repaired = store.load(&ns, 8, &all(&[1, 2, 3]));
702	            assert!(repaired.errors.is_empty(), "{label}: {:?}", repaired.errors);
703	            assert_eq!(repaired.vectors, vectors, "{label}");
704	            assert_eq!(store.keys_on_disk(), [1, 2, 3], "{label}");
705	        }
706	    }
