741	    /// Files a crashed writer left behind (a temporary file, a segment it
742	    /// renamed but never listed) are invisible to readers and removed by the
743	    /// next write.
744	    #[test]
745	    fn leftovers_of_an_interrupted_write_should_be_ignored_then_removed() {
746	        let (_dir, store) = store();
747	        store
748	            .commit_with(&namespace(), 2, &[1], &live(&[1, 2]), false, &mut || {})
749	            .unwrap();
750	        fs::write(store.dir.join(".manifest.json.1.tmp"), "{partial").unwrap();
751	        let mut orphan = segment_header(2, 1).to_vec();
752	        orphan.extend_from_slice(&9u128.to_le_bytes());
753	        orphan.extend_from_slice(&[0; 8]);
754	        fs::write(store.dir.join(segment_file_name(&orphan)), &orphan).unwrap();
755	        let loaded = store.load(&namespace(), 2, &all(&[1, 9]));
756	        assert!(loaded.errors.is_empty(), "{:?}", loaded.errors);
757	        assert_eq!(loaded.vectors, live(&[1]));
758	        assert_eq!(store.keys_on_disk(), [1, 9]);
759	        store
760	            .commit_with(&namespace(), 2, &[2], &live(&[1, 2]), false, &mut || {})
761	            .unwrap();
762	        assert_eq!(store.keys_on_disk(), [1, 2]);
763	        let names: Vec<String> = fs::read_dir(&store.dir)
764	            .unwrap()
765	            .map(|entry| entry.unwrap().file_name().to_string_lossy().into_owned())
766	            .filter(|name| name.ends_with(".tmp"))
767	            .collect();
768	        assert!(names.is_empty(), "{names:?}");
769	    }
